package com.signalchain.app.agent
data class AgentParams(val preEmphCoeff:Double=.97,val alpha:Double=1.2,val beta:Double=.1,val gainSmooth:Double=.7,val useSpectralSubtraction:Boolean=true,val useMlPostfilter:Boolean=false,val vadHangoverFrames:Int=0,val useEq:Boolean=true,val eqGain:Double=.6,val compressionRatio:Double=1.8,val compressionMakeupDb:Double=6.0)
data class AgentDecision(val mode:String,val rationale:String,val params:AgentParams)
object DecisionAgent{fun decide(snr:Double,stationary:Boolean,activity:Double):AgentDecision{var p=AgentParams();val mode:String;var r:String;if(snr>15){p=p.copy(useSpectralSubtraction=false,alpha=1.0,beta=1.0,useEq=false,eqGain=0.0,compressionRatio=1.0,compressionMakeupDb=0.0);mode="Light touch";r="High estimated SNR: spectral subtraction, EQ, and compression are all bypassed to preserve the original signal."}else if(snr>=5&&stationary){mode="Classical DSP";r="Moderate SNR with stationary noise: spectral subtraction + Wiener filtering with light EQ and mild compression."}else{p=p.copy(alpha=1.45,beta=.07,gainSmooth=.82,useMlPostfilter=true,eqGain=1.0,compressionRatio=2.0,compressionMakeupDb=10.0);mode="Full adaptive";r="Low SNR or non-stationary noise: stronger adaptive filtering, ML post-filter, full EQ, and moderate compression applied."};if(activity<.30){p=p.copy(vadHangoverFrames=5);r+=" Sparse speech detected; VAD hangover is widened."};return AgentDecision(mode,r,p)}}
